-- Lectores nativos: protege autoría, pertenencia y ambas sucursales.
-- Sin escritores, cambios de saldo, filas, firmas ni ACL. Sólo MCP tras revisión.
SET LOCAL lock_timeout='250ms';
SET LOCAL statement_timeout='4s';
DO $crm_call_metrics_delta$
DECLARE v_item jsonb; v_oid oid; v_source text; v_metadata jsonb; v_current jsonb;
BEGIN
 FOR v_item IN SELECT value FROM jsonb_array_elements($crm_call_metrics_manifest$[{"signature":"public.crm_objection_frequency(integer,timestamp with time zone,text,uuid)","acl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","config":["search_path=public, pg_temp"],"owner":"postgres","security_definer":true,"before":"5ffb8e72478ef8463056f045544832fe","after":"9a2a9d28fd39f427abfe1fe163652669","definition":"CREATE OR REPLACE FUNCTION public.crm_objection_frequency(p_org integer, p_since timestamp with time zone, p_timezone text, p_objection uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE v_result jsonb;\nBEGIN\n PERFORM public.fn_assert_acceso_org(p_org);\n -- El permiso elevado nunca acredita un propietario/creador sin miembro activo.\n IF auth.uid() IS NULL AND coalesce(auth.role(),'')<>'service_role' THEN\n  RAISE EXCEPTION 'sin_sesion' USING ERRCODE='42501';\n END IF;\n IF auth.uid() IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.organization_members m\n  WHERE m.organization_id=p_org AND m.user_id=auth.uid() AND m.is_active) THEN\n  RAISE EXCEPTION 'sin_permiso' USING ERRCODE='42501';\n END IF;\n IF p_since IS NULL OR p_since>now() OR p_since<now()-interval '92 days' OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=p_timezone) THEN RAISE EXCEPTION 'periodo_invalido' USING errcode='22023'; END IF;\n IF p_objection IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.objections WHERE id=p_objection AND organization_id=p_org) THEN RAISE EXCEPTION 'objecion_no_encontrada' USING errcode='P0002'; END IF;\n WITH visible AS MATERIALIZED (\n SELECT h.*,c.opportunity_id FROM public.crm_objection_hits(p_org,p_since,now(),NULL) h\n JOIN public.calls c ON c.id=h.call_id AND c.organization_id=p_org\n LEFT JOIN public.opportunities o ON o.id=c.opportunity_id AND o.organization_id=p_org\n LEFT JOIN public.customers customer ON customer.id=c.customer_id AND customer.organization_id=p_org\n WHERE (p_objection IS NULL OR h.objection_id=p_objection)\n AND (c.user_id=auth.uid() OR public.fn_crm_tiene_permiso(p_org,'crm.calls.view_all'))\n AND (c.customer_id IS NULL OR EXISTS(SELECT 1 FROM public.customers cu\n   WHERE cu.id=c.customer_id AND cu.organization_id=p_org\n    AND (cu.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=cu.branch_id AND b.organization_id=p_org))\n    AND (auth.uid() IS NULL OR public.app_branch_access(cu.branch_id::integer))))\n AND (c.opportunity_id IS NULL OR EXISTS(SELECT 1 FROM public.opportunities op\n   WHERE op.id=c.opportunity_id AND op.organization_id=p_org\n    AND op.customer_id IS NOT DISTINCT FROM c.customer_id\n    AND (op.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=op.branch_id AND b.organization_id=p_org))\n    AND (auth.uid() IS NULL OR public.app_branch_access(op.branch_id::integer))))\n -- crm_objection_hits conserva su núcleo privado; un análisis con referencia\n -- de transcripción ajena no acredita frecuencia ni citas de esta llamada.\n AND coalesce((SELECT a.transcript_id IS NULL OR EXISTS(SELECT 1 FROM public.call_transcripts t\n  WHERE t.id=a.transcript_id AND t.organization_id=p_org AND t.call_id=c.id)\n  FROM public.call_analyses a WHERE a.call_id=c.id AND a.organization_id=p_org\n  ORDER BY a.created_at DESC,a.id DESC LIMIT 1),false)\n ), totals AS (\n SELECT objection_id,count(*) call_count,count(*) FILTER(WHERE advanced) advanced_count,\n count(DISTINCT opportunity_id) opportunity_count,count(DISTINCT opportunity_id) FILTER(WHERE advanced) advanced_opportunity_count FROM visible GROUP BY objection_id\n ) SELECT jsonb_build_object(\n 'frequencies',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM totals t),'[]'::jsonb),\n 'weeks',coalesce((SELECT jsonb_agg(to_jsonb(w) ORDER BY week) FROM (\n SELECT to_char(date_trunc('week',started_at AT TIME ZONE p_timezone),'YYYY-MM-DD') week,count(*) call_count FROM visible GROUP BY 1) w),'[]'::jsonb),\n 'calls',CASE WHEN p_objection IS NULL THEN '[]'::jsonb ELSE coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY started_at DESC,call_id) FROM (\n SELECT v.call_id,v.started_at,v.advanced,anchor.start_ms,\n coalesce(nullif(trim(concat_ws(' ',customer.first_name,customer.last_name)),''),c.to_number,c.from_number) customer_name,\n coalesce(nullif(trim(concat_ws(' ',p.first_name,p.last_name)),''),'') seller_name\n FROM visible v JOIN public.calls c ON c.id=v.call_id AND c.organization_id=p_org\n LEFT JOIN public.customers customer ON customer.id=c.customer_id AND customer.organization_id=p_org\n LEFT JOIN public.profiles p ON p.id=c.user_id\n LEFT JOIN LATERAL (SELECT s.start_ms FROM public.call_transcripts t JOIN public.call_transcript_segments s ON s.transcript_id=t.id AND s.organization_id=p_org\n WHERE t.call_id=c.id AND t.organization_id=p_org AND t.status='completed' AND s.speaker_role='customer' AND v.quote<>'' AND position(lower(v.quote) IN lower(s.text))>0 ORDER BY t.completed_at DESC,s.start_ms LIMIT 1) anchor ON true\n ORDER BY v.started_at DESC,v.call_id LIMIT 100) r),'[]'::jsonb) END,\n 'responses',CASE WHEN p_objection IS NULL THEN '[]'::jsonb ELSE coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY advanced_count DESC,used_count DESC,response_text) FROM (\n SELECT min(btrim(r.response_text)) response_text,count(DISTINCT r.call_id) used_count,count(DISTINCT r.call_id) FILTER(WHERE v.advanced) advanced_count\n FROM public.objection_responses r JOIN visible v ON v.call_id=r.call_id AND v.objection_id=r.objection_id\n WHERE r.organization_id=p_org AND r.objection_id=p_objection\n AND (r.segment_id IS NULL OR EXISTS(SELECT 1 FROM public.call_transcript_segments s\n  JOIN public.call_transcripts t ON t.id=s.transcript_id AND t.organization_id=p_org\n  WHERE s.id=r.segment_id AND s.organization_id=p_org AND t.call_id=r.call_id))\n GROUP BY lower(regexp_replace(btrim(r.response_text),'\\s+',' ','g'))\n HAVING count(DISTINCT r.call_id) FILTER(WHERE v.advanced)>0 LIMIT 20) r),'[]'::jsonb) END\n ) INTO v_result;\n RETURN v_result;\nEND;$function$\n"},{"signature":"public.crm_voice_agent_metrics(integer,uuid,integer,integer,integer)","acl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","config":["search_path=public, pg_temp"],"owner":"postgres","security_definer":true,"before":"815735d5ff4d1d1fd57c83ca6749aedd","after":"77dc883fd3dc671809c06428d66641d8","definition":"CREATE OR REPLACE FUNCTION public.crm_voice_agent_metrics(p_org integer, p_agent uuid, p_days integer DEFAULT 30, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare v_result jsonb;\nbegin\n  -- El ledger es privado: no se concede SELECT a authenticated.\n  -- El wrapper sólo expone el agregado tras las guardas de sesión y visibilidad.\n  if auth.uid() is null and coalesce(auth.role(),'') <> 'service_role' then\n    raise exception 'sin_sesion' using errcode='42501';\n  end if;\n  perform public.fn_crm_exigir_permiso(p_org, array['crm.campaigns.manage']);\n -- El permiso elevado nunca acredita un propietario/creador sin miembro activo.\n IF auth.uid() IS NULL AND coalesce(auth.role(),'')<>'service_role' THEN\n  RAISE EXCEPTION 'sin_sesion' USING ERRCODE='42501';\n END IF;\n IF auth.uid() IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.organization_members m\n  WHERE m.organization_id=p_org AND m.user_id=auth.uid() AND m.is_active) THEN\n  RAISE EXCEPTION 'sin_permiso' USING ERRCODE='42501';\n END IF;\n  if p_days is null or p_days not in (7,30,90) or p_limit is null or p_limit not between 1 and 100\n     or p_offset is null or p_offset < 0 or p_offset > 100000 then\n    raise exception 'parametros_invalidos' using errcode='22023';\n  end if;\n  if not exists(select 1 from public.voice_agents a where a.id=p_agent and a.organization_id=p_org) then\n    raise exception 'agente_no_encontrado' using errcode='P0002';\n  end if;\n  with visible as materialized (\n    select v.*, c.full_name as customer_name,\n      case when v.campaign_id is not null then 'campaign'\n           when v.stage_agent_id is not null then 'stage' else 'direct' end as source\n    from public.voice_agent_calls v\n    left join public.customers c on c.id=v.customer_id and c.organization_id=p_org\n    left join public.calls n on n.id=v.call_id and n.organization_id=p_org\n    where v.organization_id=p_org and v.voice_agent_id=p_agent\n      and v.created_at >= now()-make_interval(days=>p_days)\n      AND (v.customer_id IS NULL OR EXISTS(SELECT 1 FROM public.customers cu\n   WHERE cu.id=v.customer_id AND cu.organization_id=p_org\n    AND (cu.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=cu.branch_id AND b.organization_id=p_org))\n    AND (auth.uid() IS NULL OR public.app_branch_access(cu.branch_id::integer))))\n AND (v.opportunity_id IS NULL OR EXISTS(SELECT 1 FROM public.opportunities op\n   WHERE op.id=v.opportunity_id AND op.organization_id=p_org\n    AND op.customer_id IS NOT DISTINCT FROM v.customer_id\n    AND (op.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=op.branch_id AND b.organization_id=p_org))\n    AND (auth.uid() IS NULL OR public.app_branch_access(op.branch_id::integer))))\n      AND (v.campaign_id IS NULL OR EXISTS(SELECT 1 FROM public.voice_agent_campaigns vc WHERE vc.id=v.campaign_id AND vc.organization_id=p_org))\n      AND (v.call_id IS NULL OR (n.id IS NOT NULL\n       AND (v.customer_id IS NULL OR n.customer_id IS NOT DISTINCT FROM v.customer_id)\n       AND (v.opportunity_id IS NULL OR n.opportunity_id IS NOT DISTINCT FROM v.opportunity_id)\n       AND (n.user_id=auth.uid() OR public.fn_crm_tiene_permiso(p_org,'crm.calls.view_all'))\n AND (n.customer_id IS NULL OR EXISTS(SELECT 1 FROM public.customers cu\n   WHERE cu.id=n.customer_id AND cu.organization_id=p_org\n    AND (cu.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=cu.branch_id AND b.organization_id=p_org))\n    AND (auth.uid() IS NULL OR public.app_branch_access(cu.branch_id::integer))))\n AND (n.opportunity_id IS NULL OR EXISTS(SELECT 1 FROM public.opportunities op\n   WHERE op.id=n.opportunity_id AND op.organization_id=p_org\n    AND op.customer_id IS NOT DISTINCT FROM n.customer_id\n    AND (op.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=op.branch_id AND b.organization_id=p_org))\n    AND (auth.uid() IS NULL OR public.app_branch_access(op.branch_id::integer))))))\n  ), credit as (\n    select coalesce(sum(case when r.settled_at is not null then r.minutes_charged else 0 end),0)::bigint as charged\n    from public.crm_voice_credit_reservations r join visible v on v.id=r.voice_agent_call_id\n    where r.organization_id=p_org\n  ), legacy as (\n    select coalesce(sum(v.credits_reserved),0)::bigint as charged from visible v\n    where v.credits_settled_at is not null and not exists(\n      select 1 from public.crm_voice_credit_reservations r\n      where r.organization_id=p_org and r.voice_agent_call_id=v.id\n    )\n  ), statuses as (\n    select status,count(*)::integer as total from visible group by status\n  ), tools as (\n    select t.tool,t.status,count(*)::integer as total\n    from public.voice_agent_tool_runs t join visible v on v.id=t.voice_agent_call_id\n    where t.organization_id=p_org group by t.tool,t.status\n  ), recent as (\n    select id,call_id,customer_name,status,outcome,duration_seconds,created_at,source,last_error_code\n    from visible order by created_at desc,id desc limit p_limit offset p_offset\n  )\n  select jsonb_build_object(\n    'period_days',p_days,'total',count(*)::integer,\n    'effective',count(*) filter(where status in ('completed','transferred'))::integer,\n    'average_duration_seconds',round(avg(duration_seconds) filter(where status in ('completed','transferred')),1),\n    'credits_consumed',(select charged from credit)+(select charged from legacy),\n    'omissions',jsonb_build_object(\n      'rne_excluded',count(*) filter(where status='skipped' and last_error_code='RNE')::integer,\n      'law_rescheduled',count(*) filter(where status in ('pending','queued') and last_error_code='LEY2300')::integer,\n      'other_skipped',count(*) filter(where status='skipped' and last_error_code is distinct from 'RNE')::integer\n    ),\n    'statuses',coalesce((select jsonb_agg(to_jsonb(s) order by s.status) from statuses s),'[]'::jsonb),\n    'tools',coalesce((select jsonb_agg(to_jsonb(t) order by t.tool,t.status) from tools t),'[]'::jsonb),\n    'rows',coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at desc,r.id desc) from recent r),'[]'::jsonb),\n    'limit',p_limit,'offset',p_offset\n  ) into v_result from visible;\n  return v_result;\nend $function$\n"},{"signature":"public.crm_voice_campaign_detail(integer,uuid,integer)","acl":"{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}","config":["search_path=public, pg_temp"],"owner":"postgres","security_definer":true,"before":"ed560597762e6e8608bbd77bd09afe5e","after":"37fee3e69506f02f3e2ce4600f40019f","definition":"CREATE OR REPLACE FUNCTION public.crm_voice_campaign_detail(p_org integer, p_campaign uuid, p_page integer DEFAULT 1)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare v_campaign jsonb; v_result jsonb; v_tz text;\nbegin\n perform public.fn_crm_exigir_permiso(p_org,array['crm.opportunities.view']);\n -- El permiso elevado nunca acredita un propietario/creador sin miembro activo.\n IF auth.uid() IS NULL AND coalesce(auth.role(),'')<>'service_role' THEN\n  RAISE EXCEPTION 'sin_sesion' USING ERRCODE='42501';\n END IF;\n IF auth.uid() IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.organization_members m\n  WHERE m.organization_id=p_org AND m.user_id=auth.uid() AND m.is_active) THEN\n  RAISE EXCEPTION 'sin_permiso' USING ERRCODE='42501';\n END IF;\n if p_page IS NULL OR p_page<1 or p_page>100000 then raise exception 'pagina_invalida' using errcode='22023';end if;\n select jsonb_build_object('id',v.id,'updated_at',v.updated_at,'voice_agent_id',v.voice_agent_id,'target_source',v.target_source,'target_config',v.target_config,'name',v.name,'status',v.status,'agent_name',a.name,\n  'objective',v.objective,'emergency_stop',v.emergency_stop,'stopped_reason',v.stopped_reason,\n  'stopped_at',v.stopped_at,'consecutive_failures',v.consecutive_failures,\n  'max_calls_per_day',v.max_calls_per_day,'max_calls_per_hour',v.max_calls_per_hour,\n  'max_concurrent',v.max_concurrent,'schedule',v.schedule,\n  'rne_checked_at',r.checked_at,'rne_valid_until',r.valid_until,'rne_numbers_in_file',r.numbers_in_file)\n into v_campaign from public.voice_agent_campaigns v\n join public.voice_agents a on a.id=v.voice_agent_id and a.organization_id=p_org\n left join lateral(select checked_at,valid_until,numbers_in_file from public.voice_campaign_rne_checks\n   where organization_id=p_org and campaign_id=v.id order by checked_at desc,id desc limit 1)r on true\n where v.id=p_campaign and v.organization_id=p_org and v.stats->>'archived_at' is null;\n if v_campaign is null then raise exception 'campana_no_encontrada' using errcode='P0002';end if;\n select coalesce(timezone,'America/Bogota') into v_tz from public.organizations where id=p_org;\n with targets as materialized(\n  SELECT v.id,v.call_id,v.status,v.outcome,v.created_at,v.scheduled_at\n  FROM public.voice_agent_calls v\n  LEFT JOIN public.calls n ON n.id=v.call_id AND n.organization_id=p_org\n  WHERE v.organization_id=p_org AND v.campaign_id=p_campaign\n   AND EXISTS(SELECT 1 FROM public.voice_agents va WHERE va.id=v.voice_agent_id AND va.organization_id=p_org)\n   AND (v.customer_id IS NULL OR EXISTS(SELECT 1 FROM public.customers cu\n   WHERE cu.id=v.customer_id AND cu.organization_id=p_org\n    AND (cu.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=cu.branch_id AND b.organization_id=p_org))\n    AND (auth.uid() IS NULL OR public.app_branch_access(cu.branch_id::integer))))\n AND (v.opportunity_id IS NULL OR EXISTS(SELECT 1 FROM public.opportunities op\n   WHERE op.id=v.opportunity_id AND op.organization_id=p_org\n    AND op.customer_id IS NOT DISTINCT FROM v.customer_id\n    AND (op.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=op.branch_id AND b.organization_id=p_org))\n    AND (auth.uid() IS NULL OR public.app_branch_access(op.branch_id::integer))))\n   -- Un objetivo sin llamada conserva la lectura nativa de campaña. Un objetivo\n   -- con llamada oculta no reaparece como pendiente ni aumenta los totales.\n   AND (v.call_id IS NULL OR (n.id IS NOT NULL\n    AND (n.metadata->>'campaign_id' IS NULL OR n.metadata->>'campaign_id'=p_campaign::text)\n    AND (v.customer_id IS NULL OR n.customer_id IS NOT DISTINCT FROM v.customer_id)\n    AND (v.opportunity_id IS NULL OR n.opportunity_id IS NOT DISTINCT FROM v.opportunity_id)\n    AND (n.user_id=auth.uid() OR public.fn_crm_tiene_permiso(p_org,'crm.calls.view_all'))\n AND (n.customer_id IS NULL OR EXISTS(SELECT 1 FROM public.customers cu\n   WHERE cu.id=n.customer_id AND cu.organization_id=p_org\n    AND (cu.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=cu.branch_id AND b.organization_id=p_org))\n    AND (auth.uid() IS NULL OR public.app_branch_access(cu.branch_id::integer))))\n AND (n.opportunity_id IS NULL OR EXISTS(SELECT 1 FROM public.opportunities op\n   WHERE op.id=n.opportunity_id AND op.organization_id=p_org\n    AND op.customer_id IS NOT DISTINCT FROM n.customer_id\n    AND (op.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=op.branch_id AND b.organization_id=p_org))\n    AND (auth.uid() IS NULL OR public.app_branch_access(op.branch_id::integer))))))\n ), physical as materialized(\n  select c.id,c.customer_id,c.status,c.started_at,c.direction,c.answered_at,c.answered_by,c.duration_seconds\n  from public.calls c where c.organization_id=p_org and\n   (c.metadata->>'campaign_id'=p_campaign::text\n    or (c.metadata->>'campaign_id' is null and exists(select 1 from targets t where t.call_id=c.id)))\n   AND (c.user_id=auth.uid() OR public.fn_crm_tiene_permiso(p_org,'crm.calls.view_all'))\n AND (c.customer_id IS NULL OR EXISTS(SELECT 1 FROM public.customers cu\n   WHERE cu.id=c.customer_id AND cu.organization_id=p_org\n    AND (cu.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=cu.branch_id AND b.organization_id=p_org))\n    AND (auth.uid() IS NULL OR public.app_branch_access(cu.branch_id::integer))))\n AND (c.opportunity_id IS NULL OR EXISTS(SELECT 1 FROM public.opportunities op\n   WHERE op.id=c.opportunity_id AND op.organization_id=p_org\n    AND op.customer_id IS NOT DISTINCT FROM c.customer_id\n    AND (op.branch_id IS NULL OR EXISTS(SELECT 1 FROM public.branches b WHERE b.id=op.branch_id AND b.organization_id=p_org))\n    AND (auth.uid() IS NULL OR public.app_branch_access(op.branch_id::integer))))\n ), history as(\n  select c.id,c.status,c.started_at,c.duration_seconds,cu.full_name as customer_name\n  from physical c left join public.customers cu on cu.id=c.customer_id and cu.organization_id=p_org\n  order by c.started_at desc nulls last,c.id desc limit 25 offset (p_page-1)*25\n ), active as(\n  select c.id,c.status,c.started_at,cu.full_name as customer_name from physical c\n  left join public.customers cu on cu.id=c.customer_id and cu.organization_id=p_org\n  where c.status in ('dialing','ringing','in_progress')\n  order by c.started_at desc nulls last,c.id desc limit 100\n ), outcomes as(\n  select status,count(*) as n from targets group by status\n )\n select jsonb_build_object('campaign',v_campaign,'stats',jsonb_build_object(\n  'targets',(select count(*) from targets),\n  'attempts',(select count(*) from physical),\n  'today',(select count(*) from physical where (started_at at time zone v_tz)::date=(now() at time zone v_tz)::date),\n  'effective',(select count(*) from physical where public.fn_es_contacto_voz_efectivo(direction,status,answered_at,answered_by)),\n  'meetings',(select count(distinct coalesce(a.metadata->>'calendar_event_id',a.id::text)) from public.activities a\n    where a.organization_id=p_org and a.outcome='meeting_booked'\n    AND (a.call_id IS NULL OR EXISTS(SELECT 1 FROM physical p WHERE p.id=a.call_id))\n    AND (a.branch_id IS NULL OR (EXISTS(SELECT 1 FROM public.branches b WHERE b.id=a.branch_id AND b.organization_id=p_org)\n      AND (auth.uid() IS NULL OR public.app_branch_access(a.branch_id::integer))))\n    and exists(select 1 from targets t where t.id::text=a.metadata->>'voice_agent_call_id')),\n  'conversation_minutes',(select coalesce(sum(greatest(coalesce(duration_seconds,0),0)),0)/60.0 from physical),\n  'remaining_minutes',(select voice_minutes_remaining from public.comm_settings where organization_id=p_org and is_active limit 1),\n  'active_total',(select count(*) from physical where status in ('dialing','ringing','in_progress')),\n  'pending',(select count(*) from targets where status in ('pending','queued')),\n  'rescheduled',(select count(*) from targets where status in ('pending','queued') and scheduled_at>now()),\n  'outcomes',(select coalesce(jsonb_object_agg(status,n),'{}'::jsonb) from outcomes)),\n  'history',(select coalesce(jsonb_agg(to_jsonb(h)),'[]'::jsonb) from history h),\n  'active',(select coalesce(jsonb_agg(to_jsonb(a)),'[]'::jsonb) from active a),\n  'page',p_page,'timezone',v_tz) into v_result;\n return v_result;\nend;\n$function$\n"}]$crm_call_metrics_manifest$::jsonb) LOOP
  v_oid:=to_regprocedure(v_item->>'signature');
  IF v_oid IS NULL THEN RAISE EXCEPTION 'rpc_metricas_ausente' USING ERRCODE='P0001'; END IF;
  SELECT p.prosrc,(to_jsonb(p)-'prosrc'-'proargdefaults') || jsonb_build_object('function_arguments',pg_get_function_arguments(p.oid),'default_ast_without_locations',regexp_replace(p.proargdefaults::text,':location -?[0-9]+',':location <offset>','g')) INTO v_source,v_metadata FROM pg_proc p WHERE p.oid=v_oid;
  IF (SELECT p.proacl::text FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM v_item->>'acl'
   OR (SELECT to_jsonb(p.proconfig) FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM v_item->'config'
   OR (SELECT pg_get_userbyid(p.proowner) FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM v_item->>'owner'
   OR (SELECT p.prosecdef FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM (v_item->>'security_definer')::boolean THEN
   RAISE EXCEPTION 'contrato_rpc_metricas_modificado' USING ERRCODE='P0001'; END IF;
  IF md5(v_source)=v_item->>'after' THEN CONTINUE; END IF;
  IF md5(v_source) IS DISTINCT FROM v_item->>'before' THEN
   RAISE EXCEPTION 'fuente_rpc_metricas_modificada' USING ERRCODE='P0001'; END IF;
  EXECUTE v_item->>'definition';
  SELECT p.prosrc,(to_jsonb(p)-'prosrc'-'proargdefaults') || jsonb_build_object('function_arguments',pg_get_function_arguments(p.oid),'default_ast_without_locations',regexp_replace(p.proargdefaults::text,':location -?[0-9]+',':location <offset>','g')) INTO v_source,v_current FROM pg_proc p WHERE p.oid=v_oid;
  IF md5(v_source) IS DISTINCT FROM v_item->>'after' OR v_metadata IS DISTINCT FROM v_current THEN
   RAISE EXCEPTION 'contrato_rpc_metricas_no_conservado' USING ERRCODE='P0001'; END IF;
 END LOOP;
END;
$crm_call_metrics_delta$;
